-- PhantomBox Core - Migration 003
-- Adds the CLI identity-link secret to the existing authorization transaction.
--
-- The browser link generated by the CLI must prove that the visitor holds a
-- secret issued by Core for a real pending transaction. The public `reference`
-- alone is not sufficient: it is displayed in the UI and must never grant
-- access to the authentication interface.
--
-- Only a SHA-256 hash of the secret is stored. The plaintext is returned once
-- to the CLI at creation time and never persisted.
--
-- This migration ONLY ADDS two nullable columns to the existing table.
-- It does NOT alter users, sessions, email_otp_codes or any other table.
--
-- Apply manually per environment:
--   mysql -u <user> -p phantombox_core < migrations/003_add_identity_link_secret.sql

ALTER TABLE `authorization_transactions`
    ADD COLUMN `identity_link_hash`   CHAR(64) NULL
        COMMENT 'SHA-256 of the CLI identity-link secret; NULL for legacy rows'
        AFTER `poll_token_lookup`,
    ADD COLUMN `identity_link_used_at` DATETIME NULL
        COMMENT 'Set when the identity link was first redeemed for a page render'
        AFTER `identity_link_hash`;

-- Lookup index for constant-time link validation.
ALTER TABLE `authorization_transactions`
    ADD UNIQUE KEY `uq_authorization_identity_link` (`identity_link_hash`);
